VERSION='2026-11-12.1'
parser=argparse.ArgumentParser()
parser.add_argument('--mode',choices=['validate','apply'],default='validate')
args=parser.parse_args()
source=pathlib.Path('cosmos-next.html')
if not source.is_file():raise SystemExit('ERROR: root cosmos-next.html not found.')
raw=source.read_bytes();sha=hashlib.sha256(raw).hexdigest()
if sha not in (SOURCE_SHA,METRO_SHA,TARGET_SHA):raise SystemExit('ERROR: unexpected frontend SHA '+sha+'. Expected exact v9.4.9; nothing changed.')
configfile=pathlib.Path('cosmos-legal-config.json')
if not configfile.is_file():raise SystemExit('ERROR: create cosmos-legal-config.json with real operator/contact values (Item 07). No files changed.')
try:cfg=json.loads(configfile.read_text())
except Exception as exc:raise SystemExit('ERROR: invalid cosmos-legal-config.json: '+str(exc))
keys=['operator_name','legal_email','mailing_address','dmca_email']
for key in keys:
  val=cfg.get(key,'')
  if not isinstance(val,str) or len(val.strip())<6 or len(val)>240 or 'REPLACE' in val.upper() or 'EXAMPLE' in val.upper() or '<' in val or '>' in val:
    raise SystemExit('ERROR: legal config field '+key+' must be a real, non-placeholder value. No files changed.')
if '@' not in cfg['legal_email'] or '@' not in cfg['dmca_email']:
  raise SystemExit('ERROR: use working email addresses in legal config. No files changed.')
if cfg.get('approved_for_publication') is not True:
  raise SystemExit('ERROR: set approved_for_publication to true in cosmos-legal-config.json only AFTER confirming real operator details and legal review. No files changed.')
for path in POLICIES:
  existing=pathlib.Path(path)
  if existing.exists() and 'COSMOS_LEGAL_VERSION: '+VERSION not in existing.read_text(errors='replace'):
    raise SystemExit('ERROR: '+path+' exists but was not generated by this installer. Will not overwrite it.')
  if existing.exists() and '__PLACEHOLDER_' in existing.read_text(errors='replace'):
    raise SystemExit('ERROR: placeholder in '+path+'; review the file before installing.')
patch=zlib.decompress(base64.b85decode(LEGAL_FROM_METRO_PATCH_B85)).decode() if sha==METRO_SHA else zlib.decompress(base64.b85decode(''.join(PATCH_B85))).decode()
with tempfile.TemporaryDirectory() as td:
  temp=pathlib.Path(td)/'cosmos-v950.patch';temp.write_text(patch)
  if sha in (SOURCE_SHA,METRO_SHA):
    run=subprocess.run(['git','apply','--check',str(temp)],capture_output=True,text=True)
    if run.returncode:raise SystemExit('ERROR: patch does not apply: '+run.stderr)
  doc_outputs={}
  for name,payload in POLICIES.items():
    value=zlib.decompress(base64.b85decode(payload)).decode()
    for placeholder,field in [('{{OPERATOR_NAME}}','operator_name'),('{{LEGAL_EMAIL}}','legal_email'),('{{LEGAL_ADDRESS}}','mailing_address'),('{{DMCA_EMAIL}}','dmca_email')]:
      value=value.replace(placeholder,html.escape(cfg[field],quote=True))
    value=value.replace('<!doctype html>', '<!doctype html><!-- COSMOS_LEGAL_VERSION: '+VERSION+' -->',1)
    if '{{' in value:raise SystemExit('ERROR: legal document placeholder remains in '+name)
    doc_outputs[name]=value
  print('Source hash valid, patch check green, real operator config supplied, '+str(len(doc_outputs))+' legal pages ready.')
  if args.mode=='validate':
    print('VALIDATION GREEN: No files were changed.');sys.exit(0)
  if sha in (SOURCE_SHA,METRO_SHA):
    result=subprocess.run(['git','apply',str(temp)],capture_output=True,text=True)
    if result.returncode:raise SystemExit('ERROR: patch apply failed: '+result.stderr)
  actual=hashlib.sha256(source.read_bytes()).hexdigest()
  if actual!=TARGET_SHA:
    source.write_bytes(raw);raise SystemExit('ERROR: resulting hash mismatch; original HTML restored.')
  for name,value in doc_outputs.items():pathlib.Path(name).write_text(value,encoding='utf-8')
  print('APPLIED v9.5.0: Metro layout corrected; policies generated with verified operator details.')
